package com.fintrack.khmtomnenh.productimage.entity; import com.fasterxml.jackson.annotation.JsonIgnore; import com.fintrack.khmtomnenh.product.entity.Product; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; import org.hibernate.annotations.CreationTimestamp;
@Entity @Table(name="product_images") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class ProductImage {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(name="image_url",nullable=false,length=1000) private String imageUrl; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;}
